Mean examples

na.rmvartypelevel and dfdeff



ess_des |&gt;
  filter(cntry == "IS") |&gt;
  summarize(
    H1 = survey_mean(News),
    H2 = survey_mean(News, na.rm = TRUE)
  )

# A tibble: 1 × 4
     H1 H1_se    H2 H2_se
  &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt;
1    NA   NaN  56.9  3.27





ess_des |&gt;
  filter(cntry == "IS") |&gt;
  summarize(
    H1 = survey_mean(News, na.rm = TRUE, vartype = c("se", "ci", "var", "cv")),
    H2 = survey_mean(News, na.rm = TRUE, vartype = NULL)
  )

# A tibble: 1 × 7
     H1 H1_se H1_low H1_upp H1_var  H1_cv    H2
  &lt;dbl&gt; &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt; &lt;dbl&gt;
1  56.9  3.27   50.4   63.3   10.7 0.0575  56.9





ess_des |&gt;
  filter(cntry == "IS") |&gt;
  summarize(
    H1 = survey_mean(News, na.rm = TRUE, vartype = "ci", level = 0.95),
    H2 = survey_mean(News, na.rm = TRUE, vartype = "ci", level = 0.8),
    H3 = survey_mean(News, na.rm = TRUE, vartype = "ci", level = 0.95, df = 10)
  )

# A tibble: 1 × 9
     H1 H1_low H1_upp    H2 H2_low H2_upp    H3 H3_low H3_upp
  &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt; &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt; &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt;
1  56.9   50.4   63.3  56.9   52.7   61.1  56.9   49.6   64.1





ess_des |&gt;
  filter(cntry == "IS") |&gt;
  summarize(H1 = survey_mean(News, na.rm = TRUE, deff = "replace"))

# A tibble: 1 × 3
     H1 H1_se H1_deff
  &lt;dbl&gt; &lt;dbl&gt;   &lt;dbl&gt;
1  56.9  3.27    1.39







na.rm removes NA before calculation, similar to many other functions in R
vartype can choose no option OR multiple
level and df control confidence intervals
deff is a design effect, a ratio of the variance under this design compared to a design which is SRS, &gt;1 means less statistically efficient

Proportion example: 2 ways

survey_mean()survey_prop()



ess_des |&gt;
  filter(cntry == "SE") |&gt;
  summarize(
    across(
      c(Volunteer_12, Volunteer_01),
      ~ survey_mean(.x, na.rm = TRUE)
    )
  )

# A tibble: 1 × 4
  Volunteer_12 Volunteer_12_se Volunteer_01 Volunteer_01_se
         &lt;dbl&gt;           &lt;dbl&gt;        &lt;dbl&gt;           &lt;dbl&gt;
1         1.74          0.0139        0.260          0.0139





ess_des |&gt;
  filter(cntry == "SE", !is.na(Volunteer_Factor)) |&gt;
  group_by(Volunteer_Factor) |&gt;
  summarize(p = survey_prop())

# A tibble: 2 × 3
  Volunteer_Factor     p   p_se
  &lt;fct&gt;            &lt;dbl&gt;  &lt;dbl&gt;
1 Yes              0.260 0.0139
2 No               0.740 0.0139







survey_mean method only works for binary outcomes, bonus of being able to use across to estimate many outcomes at once
survey_prop can be used for only one outcome at a time, can work for variables with more than 2 levels

Proportion example: arguments
prop_method argument in survey_mean()/survey_prop()

ess_des |&gt;
  filter(cntry == "SE", !is.na(Volunteer_Factor)) |&gt;
  group_by(Volunteer_Factor) |&gt;
  summarize(
    p1 = survey_prop(vartype = "ci", prop_method = "logit"),
    p2 = survey_prop(vartype = "ci", prop_method = "mean"),
    p3 = survey_prop(vartype = "ci", prop_method = "xlogit")
  ) |&gt;
  print(width = Inf)




See ?survey::svyciprop for details on implementation

Subgroup analysis: mean & median

NetUsage is 0 if a person uses internet never, only occasionally, or a few times a week; otherwise the reported minutes using internet on a typical day


ess_des |&gt;
  group_by(Country) |&gt;
  summarize(
    Pop = survey_total(vartype = NULL),
    NetUse_mean = survey_mean(NetUsage, na.rm = TRUE),
    NetUse_median = survey_median(NetUsage, na.rm = TRUE)
  ) |&gt;
  gt() |&gt;
  fmt_number(columns = starts_with("NetUse"), decimals = 2) |&gt;
  fmt_number(columns = Pop, decimals = 0) |&gt;
  opt_interactive()

Subgroup analysis: prop., marginal

NetFreq is how often people use the internet (categorical)
AgeGroup is a categorical age variable


ess_des |&gt;
  filter(cntry == "FR", !is.na(NetFreq), !is.na(AgeGroup)) |&gt;
  group_by(AgeGroup, NetFreq) |&gt;
  summarize(
    N = survey_total() * 10000,
    p = survey_prop() * 100
  ) |&gt;
  print(n = Inf)

Subgroup analysis: prop., joint

ess_des |&gt;
  filter(cntry == "FR", !is.na(NetFreq), !is.na(AgeGroup)) |&gt;
  group_by(interact(AgeGroup, NetFreq)) |&gt;
  summarize(
    N = survey_total() * 10000,
    p = survey_prop() * 100
  ) |&gt;
  print(n = Inf)

Exercise 1: estimate weighted mean happiness by country

happy_by_country &lt;-
  ess_des |&gt;
  filter(!is.na(Happy)) |&gt;
  group_by(Country) |&gt;
  summarize(Happy_mean = survey_mean(Happy, na.rm = TRUE))

happy_by_country

Exercise 2: calculate distribution of happiness level by country

happy_dist_country &lt;-
  ess_des |&gt;
  filter(!is.na(Happy)) |&gt;
  mutate(
    Happy_factor = factor(
      Happy,
      levels = 0:10,
      labels = c(
        "0 - Extremely unhappy", 1:9, "10 - Extremely happy"
      )
    )
  ) |&gt;
  group_by(interact(cntry, Country), Happy_factor) |&gt;
  summarize(
    n = survey_total(vartype = NULL),
    p = survey_mean(vartype = NULL)
    ) |&gt;
  ungroup()

happy_dist_country |&gt;
  print(n = Inf)

Exercise 3: identify the happiest and least happy countries

n_countries &lt;- 4

top_bottom_countries &lt;-
  happy_by_country |&gt;
  slice_max(Happy_mean, n = n_countries) |&gt;
  bind_rows(
    happy_by_country |&gt; slice_min(Happy_mean, n = n_countries)
  ) |&gt;
  pull(Country)

Exercise 5: join country shapes to mean estimates
Get a base map from {tmap} using the object World and join the mean estimates on. Crop the map to the extent of ESS using this code:
dat_sf |&gt;
  st_crop(
    st_bbox(c(xmin = -10, ymin = 32, xmax = 36, ymax = 70), crs = 4326) |&gt;
      st_transform(3035)
  )

Exercise 5: join country shapes to mean estimates

happy_shape &lt;-
  World |&gt;
  full_join(happy_by_country, by = c("name" = "Country")) |&gt;
  st_transform(3035) |&gt;
  st_crop(
    st_bbox(c(xmin = -10, ymin = 32, xmax = 36, ymax = 70), crs = 4326) |&gt;
      st_transform(3035)
  )
